mapper.select:
SELECT id, biz_type, biz_id, model_name, token_usage, status, error_msg, created_at FROM ai_call_log WHERE 1 = 1
AND biz_type = #{query.bizType}
AND status = #{query.status}
AND DATE(created_at) >= #{query.dateStart}
AND DATE(created_at) <= #{query.dateEnd}
ORDER BY created_at DESC

SELECT l.id, l.user_id, u.username, u.nickname, l.biz_type, l.biz_id, l.action, l.content, l.ip, l.created_at FROM sys_oper_log l LEFT JOIN sys_user u ON l.user_id = u.id WHERE 1 = 1
AND l.user_id = #{query.userId}
AND l.biz_type = #{query.bizType}
AND l.action = #{query.action}
AND DATE(l.created_at) >= #{query.dateStart}
AND DATE(l.created_at) <= #{query.dateEnd}
ORDER BY l.created_at DESC
